-- 0154: verb templates for the weak root types still missing after 0131 — assimilated (مثال: وَعَدَ يَعِدُ، وَضَعَ يَضَعُ،
-- وَجِلَ يَوْجَلُ; Forms IV, VIII, X), defective (ناقص: دَعَا يَدْعُو، رَمَى يَرْمِي، رَضِيَ يَرْضَى; Forms II–VI, VIII, X) and doubly
-- weak (لفيف: وَقَى يَقِي — command قِ; طَوَى يَطْوِي; اِتَّقَى، أَحْيَا، اِسْتَحْيَا). Each: a classic model verb with every form incl.
-- command and prohibition, plain "what changes" lines, and a Qurʾān verse showing the change (25 verses, checked against
-- qr_ayah.text_uthmani). Read with PAR:template:amr (0131) for how any command is made.
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:assimilated_w:daraba', 'وَعَدَ يَعِدُ — Form I', 'conjugation_template', 'I', 'assimilated_w', '{"past": "وَعَدَ", "present": "يَعِدُ", "masadir": ["وَعْدًا", "عِدَةً"], "active_participle": "وَاعِدٌ", "passive_participle": "مَوْعُودٌ", "passive_past": "وُعِدَ", "passive_present": "يُوعَدُ", "imperative": "عِدْ", "prohibition": "لَا تَعِدْ", "noun_of_place_time": ["مَوْعِدٌ"], "model": true, "cite": {"surah": 17, "ayah": 64, "needle": "وعدهم"}, "cite_more": [{"surah": 18, "ayah": 48, "needle": "موعدا"}], "changes": ["The first و drops in the present and the command of bāb ḍaraba: يَعِدُ، عِدْ.", "It comes back in the passive: يُوعَدُ.", "Noun of place and time on مَفْعِل, with kasra: مَوْعِد.", "A ي-first verb keeps its ي: يَسَرَ يَيْسِرُ."], "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:assimilated_w:fataha', 'وَضَعَ يَضَعُ — Form I', 'conjugation_template', 'I', 'assimilated_w', '{"past": "وَضَعَ", "present": "يَضَعُ", "masadir": ["وَضْعًا"], "active_participle": "وَاضِعٌ", "passive_participle": "مَوْضُوعٌ", "passive_past": "وُضِعَ", "passive_present": "يُوضَعُ", "imperative": "ضَعْ", "prohibition": "لَا تَضَعْ", "noun_of_place_time": ["مَوْضِعٌ"], "model": true, "cite": {"surah": 94, "ayah": 2, "needle": "ووضعنا عنك وزرك"}, "changes": ["The و drops in the present here too (يَضَعُ، يَهَبُ، يَقَعُ) — the fatḥa comes from a throat letter; the verb is at heart ḍaraba."], "bab_gt": "GT:form_family:bab_fataha", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_fataha', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:assimilated_w:samia', 'وَجِلَ يَوْجَلُ — Form I', 'conjugation_template', 'I', 'assimilated_w', '{"past": "وَجِلَ", "present": "يَوْجَلُ", "masadir": ["وَجَلًا"], "active_participle": "وَجِلٌ", "imperative": "اِيجَلْ", "prohibition": "لَا تَوْجَلْ", "model": true, "cite": {"surah": 15, "ayah": 53, "needle": "قالوا لا توجل"}, "changes": ["In bāb samiʿa the و stays: يَوْجَلُ، لَا تَوْجَلْ.", "In the command the و turns to ي after the kasra: اِيجَلْ."], "bab_gt": "GT:form_family:bab_samia", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_samia', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:IV:assimilated_w', 'أَوْقَدَ يُوقِدُ — Form IV', 'conjugation_template', 'IV', 'assimilated_w', '{"past": "أَوْقَدَ", "present": "يُوقِدُ", "masadir": ["إِيقَادًا"], "active_participle": "مُوقِدٌ", "passive_participle": "مُوقَدٌ", "passive_past": "أُوقِدَ", "passive_present": "يُوقَدُ", "imperative": "أَوْقِدْ", "prohibition": "لَا تُوقِدْ", "model": true, "cite": {"surah": 28, "ayah": 38, "needle": "فاوقد لي"}, "changes": ["The و stays, as a long vowel after ḍamma: يُوقِدُ.", "After kasra it becomes ي: إِيقَاد."], "form_gt": "GT:form_family:form_iv", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:VIII:assimilated_w', 'اِتَّسَقَ يَتَّسِقُ — Form VIII', 'conjugation_template', 'VIII', 'assimilated_w', '{"past": "اِتَّسَقَ", "present": "يَتَّسِقُ", "masadir": ["اِتِّسَاقًا"], "active_participle": "مُتَّسِقٌ", "imperative": "اِتَّسِقْ", "prohibition": "لَا تَتَّسِقْ", "model": true, "cite": {"surah": 84, "ayah": 18, "needle": "والقمر اذا اتسق"}, "changes": ["The first و merges into the ت of Form VIII: اِوْتَسَقَ → اِتَّسَقَ."], "form_gt": "GT:form_family:form_viii", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:X:assimilated_w', 'اِسْتَوْقَدَ يَسْتَوْقِدُ — Form X', 'conjugation_template', 'X', 'assimilated_w', '{"past": "اِسْتَوْقَدَ", "present": "يَسْتَوْقِدُ", "masadir": ["اِسْتِيقَادًا"], "active_participle": "مُسْتَوْقِدٌ", "imperative": "اِسْتَوْقِدْ", "prohibition": "لَا تَسْتَوْقِدْ", "model": true, "cite": {"surah": 2, "ayah": 17, "needle": "كمثل الذي استوقد نارا"}, "changes": ["The و stays; after kasra it becomes ي: اِسْتِيقَاد."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:assimilated_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:defective_w:nasara', 'دَعَا يَدْعُو — Form I', 'conjugation_template', 'I', 'defective_w', '{"past": "دَعَا", "present": "يَدْعُو", "masadir": ["دُعَاءً", "دَعْوَةً"], "active_participle": "دَاعٍ", "passive_participle": "مَدْعُوٌّ", "passive_past": "دُعِيَ", "passive_present": "يُدْعَى", "imperative": "اُدْعُ", "prohibition": "لَا تَدْعُ", "noun_of_place_time": ["مَدْعًى"], "model": true, "cite": {"surah": 16, "ayah": 125, "needle": "ادع الي سبيل ربك"}, "cite_more": [{"surah": 28, "ayah": 88, "needle": "ولا تدع مع الله الها اخر"}], "changes": ["The last letter is alif in the past (دَعَا، رَمَى) and shows as و / ي in the present (يَدْعُو، يَرْمِي).", "It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "bab_gt": "GT:form_family:bab_nasara", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:defective_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_nasara', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:defective_y:daraba', 'رَمَى يَرْمِي — Form I', 'conjugation_template', 'I', 'defective_y', '{"past": "رَمَى", "present": "يَرْمِي", "masadir": ["رَمْيًا"], "active_participle": "رَامٍ", "passive_participle": "مَرْمِيٌّ", "passive_past": "رُمِيَ", "passive_present": "يُرْمَى", "imperative": "اِرْمِ", "prohibition": "لَا تَرْمِ", "noun_of_place_time": ["مَرْمًى"], "model": true, "cite": {"surah": 8, "ayah": 17, "needle": "وما رميت اذ رميت"}, "changes": ["The last letter is alif in the past (دَعَا، رَمَى) and shows as و / ي in the present (يَدْعُو، يَرْمِي).", "It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:defective_y:samia', 'رَضِيَ يَرْضَى — Form I', 'conjugation_template', 'I', 'defective_y', '{"past": "رَضِيَ", "present": "يَرْضَى", "masadir": ["رِضًا", "رِضْوَانًا"], "active_participle": "رَاضٍ", "passive_participle": "مَرْضِيٌّ", "passive_past": "رُضِيَ", "passive_present": "يُرْضَى", "imperative": "اِرْضَ", "prohibition": "لَا تَرْضَ", "model": true, "cite": {"surah": 5, "ayah": 119, "needle": "رضي الله عنهم"}, "cite_more": [{"surah": 89, "ayah": 28, "needle": "راضية مرضية"}], "changes": ["In bāb samiʿa the last letter is ي in the past (رَضِيَ) and alif in the present (يَرْضَى).", "It drops in the command: اِرْضَ."], "bab_gt": "GT:form_family:bab_samia", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_samia', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:II:defective', 'سَمَّى يُسَمِّي — Form II', 'conjugation_template', 'II', 'defective_y', '{"past": "سَمَّى", "present": "يُسَمِّي", "masadir": ["تَسْمِيَةً"], "active_participle": "مُسَمٍّ", "passive_participle": "مُسَمًّى", "passive_past": "سُمِّيَ", "passive_present": "يُسَمَّى", "imperative": "سَمِّ", "prohibition": "لَا تُسَمِّ", "model": true, "cite": {"surah": 3, "ayah": 36, "needle": "واني سميتها مريم"}, "changes": ["Form II of a defective root takes the maṣdar تَفْعِلَة: تَسْمِيَة (not تَفْعِيل).", "The object noun ends in -an: مُسَمًّى."], "form_gt": "GT:form_family:form_ii", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:III:defective', 'نَادَى يُنَادِي — Form III', 'conjugation_template', 'III', 'defective_y', '{"past": "نَادَى", "present": "يُنَادِي", "masadir": ["مُنَادَاةً", "نِدَاءً"], "active_participle": "مُنَادٍ", "passive_participle": "مُنَادًى", "passive_past": "نُودِيَ", "passive_present": "يُنَادَى", "imperative": "نَادِ", "prohibition": "لَا تُنَادِ", "model": true, "cite": {"surah": 11, "ayah": 45, "needle": "ونادي نوح ربه"}, "changes": ["It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "form_gt": "GT:form_family:form_iii", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:IV:defective', 'أَعْطَى يُعْطِي — Form IV', 'conjugation_template', 'IV', 'defective_y', '{"past": "أَعْطَى", "present": "يُعْطِي", "masadir": ["إِعْطَاءً"], "active_participle": "مُعْطٍ", "passive_participle": "مُعْطًى", "passive_past": "أُعْطِيَ", "passive_present": "يُعْطَى", "imperative": "أَعْطِ", "prohibition": "لَا تُعْطِ", "model": true, "cite": {"surah": 108, "ayah": 1, "needle": "انا اعطيناك الكوثر"}, "changes": ["The last letter becomes hamza after the long alif of the maṣdar: إِعْطَاء.", "It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "form_gt": "GT:form_family:form_iv", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:V:defective', 'تَمَنَّى يَتَمَنَّى — Form V', 'conjugation_template', 'V', 'defective_y', '{"past": "تَمَنَّى", "present": "يَتَمَنَّى", "masadir": ["تَمَنِّيًا"], "active_participle": "مُتَمَنٍّ", "imperative": "تَمَنَّ", "prohibition": "لَا تَتَمَنَّ", "model": true, "cite": {"surah": 4, "ayah": 32, "needle": "ولا تتمنوا ما فضل الله"}, "changes": ["The last letter is alif in past and present (تَمَنَّى يَتَمَنَّى) and drops in the command: تَمَنَّ."], "form_gt": "GT:form_family:form_v", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:VI:defective', 'تَعَالَى يَتَعَالَى — Form VI', 'conjugation_template', 'VI', 'defective_w', '{"past": "تَعَالَى", "present": "يَتَعَالَى", "masadir": ["تَعَالِيًا"], "active_participle": "مُتَعَالٍ", "imperative": "تَعَالَ", "prohibition": "لَا تَتَعَالَ", "model": true, "cite": {"surah": 6, "ayah": 151, "needle": "قل تعالوا"}, "changes": ["The command drops the last letter: تَعَالَ — «come!» in the Qurʾān."], "form_gt": "GT:form_family:form_vi", "root_type_gt": "GT:root_type:defective_w"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:VIII:defective', 'اِشْتَرَى يَشْتَرِي — Form VIII', 'conjugation_template', 'VIII', 'defective_y', '{"past": "اِشْتَرَى", "present": "يَشْتَرِي", "masadir": ["اِشْتِرَاءً"], "active_participle": "مُشْتَرٍ", "passive_participle": "مُشْتَرًى", "passive_past": "اُشْتُرِيَ", "passive_present": "يُشْتَرَى", "imperative": "اِشْتَرِ", "prohibition": "لَا تَشْتَرِ", "model": true, "cite": {"surah": 9, "ayah": 111, "needle": "ان الله اشتري من المؤمنين"}, "changes": ["The last letter is alif in the past (دَعَا، رَمَى) and shows as و / ي in the present (يَدْعُو، يَرْمِي).", "It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "form_gt": "GT:form_family:form_viii", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:X:defective', 'اِسْتَغْنَى يَسْتَغْنِي — Form X', 'conjugation_template', 'X', 'defective_y', '{"past": "اِسْتَغْنَى", "present": "يَسْتَغْنِي", "masadir": ["اِسْتِغْنَاءً"], "active_participle": "مُسْتَغْنٍ", "imperative": "اِسْتَغْنِ", "prohibition": "لَا تَسْتَغْنِ", "model": true, "cite": {"surah": 64, "ayah": 6, "needle": "واستغني الله"}, "changes": ["The last letter is alif in the past (دَعَا، رَمَى) and shows as و / ي in the present (يَدْعُو، يَرْمِي).", "It drops in the command and after لَمْ / لَا: اُدْعُ، اِرْمِ، لَمْ يَدْعُ.", "The doer noun ends in -in when indefinite: دَاعٍ، رَامٍ (الدَّاعِي)."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:defective_y"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:lafif_mafruq', 'وَقَى يَقِي — Form I', 'conjugation_template', 'I', 'lafif_mafruq', '{"past": "وَقَى", "present": "يَقِي", "masadir": ["وِقَايَةً"], "active_participle": "وَاقٍ", "passive_participle": "مَوْقِيٌّ", "passive_past": "وُقِيَ", "passive_present": "يُوقَى", "imperative": "قِ", "prohibition": "لَا تَقِ", "model": true, "cite": {"surah": 2, "ayah": 201, "needle": "وقنا عذاب النار"}, "changes": ["First and last letters weak, apart (و … ي): the first drops like وَعَدَ, the last like رَمَى.", "So the command is one letter: قِ (قِنَا، قِهِ); likewise وَفَى → فِ."], "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:lafif_mafruq"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:I:lafif_maqrun', 'طَوَى يَطْوِي — Form I', 'conjugation_template', 'I', 'lafif_maqrun', '{"past": "طَوَى", "present": "يَطْوِي", "masadir": ["طَيًّا"], "active_participle": "طَاوٍ", "passive_participle": "مَطْوِيٌّ", "passive_past": "طُوِيَ", "passive_present": "يُطْوَى", "imperative": "اِطْوِ", "prohibition": "لَا تَطْوِ", "model": true, "cite": {"surah": 21, "ayah": 104, "needle": "يوم نطوي السماء"}, "cite_more": [{"surah": 39, "ayah": 67, "needle": "مطويات بيمينه"}], "changes": ["Middle and last letters weak, together: the middle stays sound (طَوَى), the last behaves as in رَمَى (يَطْوِي، اِطْوِ)."], "bab_gt": "GT:form_family:bab_daraba", "form_gt": "GT:form_family:form_i", "root_type_gt": "GT:root_type:lafif_maqrun"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', 'bab_daraba', 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:VIII:lafif_mafruq', 'اِتَّقَى يَتَّقِي — Form VIII', 'conjugation_template', 'VIII', 'lafif_mafruq', '{"past": "اِتَّقَى", "present": "يَتَّقِي", "masadir": ["اِتِّقَاءً"], "active_participle": "مُتَّقٍ", "imperative": "اِتَّقِ", "prohibition": "لَا تَتَّقِ", "model": true, "cite": {"surah": 33, "ayah": 1, "needle": "النبي اتق الله"}, "changes": ["The first و merges into the ت (اِوْتَقَى → اِتَّقَى); the last letter drops in the command: اِتَّقِ."], "form_gt": "GT:form_family:form_viii", "root_type_gt": "GT:root_type:lafif_mafruq"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:IV:lafif_maqrun', 'أَحْيَا يُحْيِي — Form IV', 'conjugation_template', 'IV', 'lafif_maqrun', '{"past": "أَحْيَا", "present": "يُحْيِي", "masadir": ["إِحْيَاءً"], "active_participle": "مُحْيٍ", "passive_past": "أُحْيِيَ", "passive_present": "يُحْيَا", "imperative": "أَحْيِ", "prohibition": "لَا تُحْيِ", "model": true, "cite": {"surah": 5, "ayah": 32, "needle": "احيا الناس جميعا"}, "changes": ["The middle ي stays; the last behaves as a defective verb: يُحْيِي، أَحْيِ."], "form_gt": "GT:form_family:form_iv", "root_type_gt": "GT:root_type:lafif_maqrun"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
INSERT OR IGNORE INTO ar_ling_root_form_paradigm (id, paradigm_name, paradigm_type, verb_form, root_type, paradigm_json, source_slug, source_ref, bab_key, status, layer_code) VALUES ('PAR:template:X:lafif_maqrun', 'اِسْتَحْيَا يَسْتَحْيِي — Form X', 'conjugation_template', 'X', 'lafif_maqrun', '{"past": "اِسْتَحْيَا", "present": "يَسْتَحْيِي", "masadir": ["اِسْتِحْيَاءً"], "active_participle": "مُسْتَحْيٍ", "imperative": "اِسْتَحْيِ", "prohibition": "لَا تَسْتَحْيِ", "model": true, "cite": {"surah": 2, "ayah": 26, "needle": "ان الله لا يستحيي"}, "changes": ["The middle ي stays; the last drops in the command: اِسْتَحْيِ."], "form_gt": "GT:form_family:form_x", "root_type_gt": "GT:root_type:lafif_maqrun"}', 'kmaps_synth', 'ṣarf template; model verbs and verses checked against the muṣḥaf', NULL, 'live', 'AL:150-FORM:SF:22-BAB:P');
